        { shareId, member }: { shareId: string; member: ShareMember }
    ) => debouncedRequest(queryUpdateShareMemberPermissions(shareId, member.memberId, member.permissions), abortSignal);

    return {
        getShareMembers,
        removeShareMember,
        updateShareMemberPermissions,
    };
};

